// app/quiz/page.tsx
"use client";

import {
  ScienceTechnologyIcon,
  ArtsHumanitiesIcon,
  BusinessEconomicsIcon,
  HealthMedicineIcon,
  EngineeringIcon,
  LawJusticeIcon,
  CheckSelectedIcon,
} from "@/app/components/topicIcons";

const TOPIC_ICONS: Record<string, React.ComponentType<React.SVGProps<SVGSVGElement>>> = {
  "Arts, Design & Architecture": ArtsHumanitiesIcon,
  "Business": BusinessEconomicsIcon,
  "Engineering": EngineeringIcon,
  "Law & Justice": LawJusticeIcon,
  "Medicine & Health": HealthMedicineIcon,
  "Science": ScienceTechnologyIcon,
};

interface QuizOption {
  id: string;
  label: string;
}

interface QuizQuestionData {
  questionId: string;
  questionType: "fixed_category" | "boolean_tag" | "numeric_threshold";
  questionText: string;
  subtitle?: string;
  multiSelect: boolean;
  options: QuizOption[];
  remainingCount: number;
}

export default function QuizPage() {
  const router = useRouter();
  const [question, setQuestion] = useState<QuizQuestionData | null>(null);
  const [selected, setSelected] = useState<string[]>([]);
  const [loading, setLoading] = useState(true);
  const [isDone, setIsDone] = useState(false);

  useEffect(() => {
    quizStorage.clear();
    fetch("/api/quiz/first-question")
      .then((res) => res.json())
      .then((data) => {
        setQuestion(data);
        setLoading(false);
      });
  }, []);

  function toggleOption(id: string) {
    if (question?.multiSelect) {
      setSelected((prev) =>
        prev.includes(id) ? prev.filter((s) => s !== id) : [...prev, id]
      );
    } else {
      setSelected([id]);
    }
  }

  async function handleNext() {
    if (!question || selected.length === 0) return;

    const answer: StoredAnswer = {
      questionId: question.questionId,
      questionType: question.questionType,
      selectedOptionIds: selected,
    };
    const history = quizStorage.add(answer);

    setLoading(true);
    const res = await fetch("/api/quiz/next-question", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ answers: history }),
    });
    const data = await res.json();

    if (data.done) {
      setIsDone(true);
      setQuestion(null);
      setLoading(false);
      return;
    }

    setQuestion(data);
    setSelected([]);
    setLoading(false);
  }

  async function handleBack() {
    const current = quizStorage.get();
    if (current.length === 0) return;

    const removedAnswer = current[current.length - 1];
    const history = quizStorage.removeLast();

    setLoading(true);
    setIsDone(false);

    if (history.length === 0) {
      const res = await fetch("/api/quiz/first-question");
      const data = await res.json();
      setQuestion(data);
      setSelected([]);
      setLoading(false);
      return;
    }

    const res = await fetch("/api/quiz/next-question", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ answers: history }),
    });
    const data = await res.json();

    setQuestion(data);
    setSelected(removedAnswer.selectedOptionIds);
    setLoading(false);
  }

  function handleFinish() {
    router.push("/results");
  }

  const showFinishInstead = (question?.remainingCount ?? Infinity) < 5;
  const canGoBack = quizStorage.get().length > 0 && !loading;

  return (
    <div className="mx-auto flex max-w-3xl flex-col items-center px-6 py-10">
      {/* Speech bubble + owl */}
      <div className="flex w-full items-center justify-center gap-6">
        <div className="relative min-h-[120px] w-full max-w-[420px] rounded-2xl bg-[#d9d9d9] px-8 py-6">
          {isDone ? (
            <div className="flex flex-col items-center gap-3 text-center">
              <p className="font-medium text-text-primary">
                We&apos;ve narrowed it down. Ready to see your matches?
              </p>
            </div>
          ) : loading || !question ? (
            <div className="animate-pulse space-y-2">
              <div className="h-4 w-3/4 rounded bg-gray-400/40" />
              <div className="h-4 w-1/2 rounded bg-gray-400/40" />
            </div>
          ) : (
            <>
              <h1 className="text-xl font-bold text-text-primary">
                {question.questionText}
              </h1>
              {question.subtitle && (
                <p className="mt-1 text-sm text-text-secondary">
                  {question.subtitle}
                </p>
              )}
            </>
          )}

          {/* Speech bubble point */}
          <div
            className="
              hidden sm:block
              absolute
              top-1/2
              -right-7
              -translate-y-1/2
              w-0
              h-0
              border-t-[35px]
              border-t-transparent
              border-b-[35px]
              border-b-transparent
              border-l-[35px]
              border-l-[#d9d9d9]
            "
          />
        </div>

        <div className="hidden h-24 w-24 flex-shrink-0 sm:block">
          <Image
            src={owlAsk}
            alt="Owl"
            className="h-full w-full object-contain"
          />
        </div>
      </div>

      {isDone ? (
        <div className="mt-8">
          <div
            role="button"
            tabIndex={0}
            onClick={handleFinish}
            onKeyDown={(e) => {
              if (e.key === "Enter" || e.key === " ") handleFinish();
            }}
          >
            <PrimaryButton>Finish</PrimaryButton>
          </div>
        </div>
      ) : (
        <>
          {/* Options card */}
          <div className="mt-8 w-full rounded-2xl bg-white p-6 shadow-sm">
            <div className="flex flex-wrap justify-center gap-4">
              {(question?.options ?? []).map((opt) => {
                const isSelected = selected.includes(opt.id);
                const iconSrc = TOPIC_ICONS[opt.label];

                return (
                  <button
                    key={opt.id}
                    onClick={() => toggleOption(opt.id)}
                    disabled={loading}
                    className={`w-40 rounded-xl border p-4 text-left transition disabled:opacity-40 sm:w-48 ${
                      isSelected
                        ? "border-primary bg-primary/5"
                        : "border-gray-200 bg-white hover:border-primary/40"
                    }`}
                  >
                    <div className="flex items-center justify-between">
                      {iconSrc && (
                        <div
                          className={`flex h-10 w-10 items-center justify-center rounded-full ${
                            isSelected
                              ? "bg-primary text-white"
                              : "bg-background text-primary"
                          }`}
                        >
                          <Image src={iconSrc} alt="" width={20} height={20} />
                        </div>
                      )}

                      {isSelected && (
                        <Image
                          src="/question-icons/check-selected.svg"
                          alt="Selected"
                          width={18}
                          height={18}
                          className="text-primary"
                        />
                      )}
                    </div>

                    <span className="mt-3 block text-sm font-semibold text-text-primary">
                      {opt.label}
                    </span>
                  </button>
                );
              })}
            </div>
          </div>

          {/* Back / Next row */}
          <div className="mt-6 flex w-full items-center justify-between">
            {canGoBack ? (
              <div
                role="button"
                tabIndex={0}
                onClick={handleBack}
                onKeyDown={(e) => {
                  if (e.key === "Enter" || e.key === " ") handleBack();
                }}
              >
                <SecondaryButton>Back</SecondaryButton>
              </div>
            ) : (
              <span />
            )}

            <div
              role="button"
              tabIndex={0}
              aria-disabled={selected.length === 0 || loading}
              onClick={() => {
                if (selected.length === 0 || loading) return;
                showFinishInstead ? handleFinish() : handleNext();
              }}
              onKeyDown={(e) => {
                if (
                  (e.key === "Enter" || e.key === " ") &&
                  !(selected.length === 0 || loading)
                ) {
                  showFinishInstead ? handleFinish() : handleNext();
                }
              }}
              className={
                selected.length === 0 || loading
                  ? "pointer-events-none opacity-40"
                  : ""
              }
            >
              <PrimaryButton>
                {loading
                  ? "Loading..."
                  : showFinishInstead
                  ? "Finish"
                  : "Next Question"}
              </PrimaryButton>
            </div>
          </div>
        </>
      )}
    </div>
  );
}